def set_respondents(apps, schema_editor):
    """End-of-project answers given so far: the person they are is whoever
    the link they came through was issued to."""
    FormStepResponse = apps.get_model("proposal_forms", "FormStepResponse")
    for response in FormStepResponse.objects.filter(
        project__isnull=False, link__issued_to__isnull=False
    ).select_related("link__issued_to"):
        user = response.link.issued_to
        response.respondent = user
        response.respondent_name = (
            f"{user.first_name} {user.last_name}".strip() or user.username
        )
        response.respondent_email = user.email or ""
        response.save(
            update_fields=["respondent", "respondent_name", "respondent_email"]
        )


